'use strict';
const CACHE='musonoi-static-v35-release';const STATIC=['/v35.css','/interaction-completion.css','/accounts-overview.css','/product.css','/v33.css','/v34.css','/interaction-polish.css','/account-task-polish.css','/yard-workflow.css','/offline.html','/styles.css','/field.css','/stock-map.css','/assets/field-icon.svg','/assets/metorex-ruashi-logo.png','/manifest.webmanifest','/vendor/zxing-browser-0.1.5.min.js','/vendor/jsQR-1.4.0.js'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(STATIC))));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('musonoi-static-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(u.origin!==self.location.origin||e.request.method!=='GET'||u.pathname.startsWith('/api/')||u.pathname.startsWith('/labels/'))return;if(STATIC.includes(u.pathname)&&!u.search){e.respondWith(fetch(e.request).catch(()=>caches.match(u.pathname)));return;}if(e.request.mode==='navigate'&&/^\/(?:$|sales-plans(?:\/|$)|loading-plans(?:\/|$)|export-shipments(?:\/|$)|overview(?:\/|$)|stock-map(?:\/|$)|inventory(?:\/|$)|customers(?:\/|$)|receipts(?:\/|$)|preparation(?:\/|$)|outbounds(?:\/|$)|field$|workbench(?:\/|$))/.test(u.pathname))e.respondWith(fetch(e.request).catch(()=>caches.match('/offline.html')));});
